<script setup lang="ts">
import { SearchableSelect } from '#components'
import { Wallet, RefreshCcw, Plus, Pencil, ReceiptText, History } from 'lucide-vue-next'
import type { MonthFee, ClassItem } from '~/types/models'
const { t } = useLanguage()
const supabase=useSupabase(),auth=useAuth(), periodMonth=ref(nowMonth()),periodId=ref(''),periodStatus=ref(''),classes=ref<ClassItem[]>([]),rows=ref<MonthFee[]>([]),selectedClass=ref(''),query=ref('')
const error=ref(''),success=ref(''),loading=ref(false),loaded=ref(false),saving=ref(false),settlementRows=ref<any[]>([])
const payOpen=ref(false),adjustOpen=ref(false),historyOpen=ref(false),receiptOpen=ref(false)
const chosen=ref<MonthFee|null>(null),payAmount=ref(0),paidOn=ref(''),payMethod=ref(''),payNote=ref('')
const paymentKey=useRequestKey()
const history=ref<any[]>([]),receipt=ref<any|null>(null)
const filtered=computed(()=>rows.value.filter(r=>(!selectedClass.value||r.class_id===selectedClass.value)&&(`${r.student_name} ${r.student_code} ${r.class_name}`.toLowerCase().includes(query.value.toLowerCase()))))
const total=(key:keyof MonthFee)=>filtered.value.reduce((a,r)=>a+Number(r[key]||0),0)
const periodReview=computed(()=>{const teacherEntitlement=settlementRows.value.reduce((sum,row)=>sum+Number(row.teacher_entitlement||0),0);const teacherPaid=settlementRows.value.reduce((sum,row)=>sum+Number(row.settled_total||0),0);return {month:periodMonth.value,registrations:rows.value.length,paid:money(rows.value.reduce((sum,row)=>sum+Number(row.paid_total||0),0)),outstanding:money(rows.value.reduce((sum,row)=>sum+Number(row.balance_due||0),0)),teacherEntitlement:money(teacherEntitlement),teacherPaid:money(teacherPaid),teacherOutstanding:money(teacherEntitlement-teacherPaid)}})
async function load(){if(!supabase)return;loading.value=true;loaded.value=false;rows.value=[];settlementRows.value=[];periodId.value='';periodStatus.value='';error.value='';try{
 const [p,cl]=await Promise.all([supabase.from('billing_periods').select('id,status').eq('year_month',monthStart(periodMonth.value)).maybeSingle(),supabase.from('class_rooms').select('id,title').order('title')]);if(p.error||cl.error)throw p.error||cl.error;classes.value=(cl.data||[]) as ClassItem[];periodId.value=p.data?.id||'';periodStatus.value=p.data?.status||'';
 if(periodId.value){const [accounts,settlements]=await Promise.all([allRows(()=>supabase.from('month_fee_overview').select('*').eq('period_id',periodId.value).order('class_name').order('id')),allRows(()=>supabase.from('teacher_settlement_summary').select('teacher_entitlement,settled_total').eq('period_id',periodId.value).order('class_id'))]);rows.value=accounts as MonthFee[];settlementRows.value=settlements}else rows.value=[]
 loaded.value=true
 }catch(e:any){error.value=errText(e)}finally{loading.value=false}}
async function createMonth(){if(!supabase||saving.value)return;saving.value=true;error.value='';success.value='';try{if(!isValidMonth(periodMonth.value))throw Error(t('financialUi.finance.monthInvalid'));const r=await supabase.rpc('ensure_billing_month',{p_month:monthStart(periodMonth.value)});if(r.error)throw r.error;success.value=t('financialUi.finance.monthCreated',{count:r.data||0});await load()}catch(e:any){error.value=errText(e)}finally{saving.value=false}}
function startPay(r:MonthFee){paymentKey.reset();chosen.value=r;payAmount.value=Number(r.balance_due);paidOn.value='';payMethod.value='';payNote.value='';payOpen.value=true}
async function savePayment(){if(!supabase||!chosen.value||saving.value)return;saving.value=true;error.value='';success.value='';try{if(payAmount.value<=0||payAmount.value>Number(chosen.value.balance_due)||!paidOn.value||!payMethod.value)throw Error(t('financialUi.finance.paymentAmountInvalid'));const res=await supabase.rpc('record_tuition_payment',{p_membership:chosen.value.id,p_amount:Number(payAmount.value),p_date:paidOn.value,p_method:payMethod.value,p_note:payNote.value||null,p_request:paymentKey.forPayload({id:chosen.value.id,amount:payAmount.value,date:paidOn.value,method:payMethod.value,note:payNote.value})});if(res.error)throw res.error;receipt.value={...res.data,student_name:chosen.value.student_name,student_code:chosen.value.student_code,class_name:chosen.value.class_name};payOpen.value=false;receiptOpen.value=true;success.value=t('financialUi.finance.paymentSaved');await load()}catch(e:any){error.value=errText(e)}finally{saving.value=false}}
function startAdjust(r:MonthFee){chosen.value=r;adjustOpen.value=true}
async function openHistory(r:MonthFee){if(!supabase)return;chosen.value=r;error.value='';const q=await supabase.from('payments').select('*').eq('monthly_membership_id',r.id).order('created_at',{ascending:false});if(q.error)error.value=errText(q.error);else{history.value=q.data||[];historyOpen.value=true}}
async function voidPay(p:any){if(!supabase||!chosen.value)return;const reason=window.prompt(t('financialUi.finance.voidPrompt'));if(!reason)return;const r=await supabase.rpc('void_payment',{p_id:p.id,p_reason:reason});if(r.error)error.value=errText(r.error);else{success.value=t('financialUi.finance.paymentVoided');await openHistory(chosen.value);await load()}}
function printReceipt(){ window.print() }
onMounted(load)
</script>
<template><div><PageTitle :title="t('financialUi.finance.title')" :subtitle="t('financialUi.finance.subtitle')"><a href="#record-payment" class="btn primary">{{t('agreements.recordPayment')}}</a><button class="btn" :disabled="loading" @click="load"><RefreshCcw :size="17"/> {{ t('financialUi.refresh') }}</button></PageTitle><Notice :message="error" kind="error"/><Notice :message="success" kind="success"/>
<section class="card" style="margin-bottom:20px"><div class="card-header"><div><h3>{{ t('financialUi.finance.selectMonth') }}</h3><p>{{ t('financialUi.finance.independentMonth') }}</p></div><Wallet :size="22" class="muted"/></div><div class="table-toolbar"><input v-model="periodMonth" type="month" style="max-width:210px" @change="load"/><button class="btn primary" :disabled="saving||(!!periodId&&periodStatus!=='open')" @click="createMonth"><Plus :size="16"/>{{periodId?t('financialUi.finance.refreshMonth'):t('financialUi.finance.createMonth')}}</button><span v-if="periodId" :class="['badge',periodStatus==='open'?'success':'warning']">{{periodStatus==='open'?t('financialUi.teacherSettlements.openMonth'):t('financialUi.teacherSettlements.closedMonth')}}</span></div><p class="hint">{{ t('financialUi.finance.monthHint') }}</p></section>
<PaymentRecorder @saved="load"/><PeriodControls v-if="loaded&&periodId" :period-id="periodId" :status="periodStatus" :review="periodReview" @changed="load"/><template v-if="loaded&&periodId"><div class="kpi-grid"><div class="card kpi"><div><small>{{ t('financialUi.monthlyReport.tuitionReceivable') }}</small><strong>{{money(total('amount_due'))}}</strong></div></div><div class="card kpi"><div><small>{{ t('financialUi.finance.paid') }}</small><strong>{{money(total('paid_total'))}}</strong></div></div><div class="card kpi"><div><small>{{ t('financialUi.finance.outstanding') }}</small><strong>{{money(total('balance_due'))}}</strong></div></div><div class="card kpi"><div><small>{{ t('financialUi.finance.teacherEntitlement') }}</small><strong>{{money(total('teacher_entitlement'))}}</strong></div></div></div>
<section class="card"><div class="card-header"><div><h3>{{ t('financialUi.finance.studentAccounts') }}</h3><p>{{ t('financialUi.finance.tableSubtitle') }}</p></div><span class="badge info">{{ t('financialUi.finance.count',{count:filtered.length}) }}</span></div><div class="table-toolbar"><SearchableSelect v-model="selectedClass" :options="classes" label-key="title" :placeholder="t('financialUi.monthlyReport.allClasses')" /><input v-model="query" :placeholder="t('financialUi.finance.search')"/></div><div class="table-wrap"><table class="data-table"><thead><tr><th>{{ t('financialUi.student') }}</th><th>{{ t('financialUi.class') }}</th><th>{{ t('financialUi.monthlyReport.originalFee') }}</th><th>{{ t('financialUi.monthlyReport.applicableFee') }}</th><th>{{ t('financialUi.monthlyReport.prorationBasis') }}</th><th>{{ t('financialUi.monthlyReport.discount') }}</th><th>{{ t('financialUi.monthlyReport.due') }}</th><th>{{ t('financialUi.finance.paid') }}</th><th>{{ t('financialUi.finance.outstanding') }}</th><th>{{ t('financialUi.finance.teacherShare') }}</th><th>{{ t('financialUi.monthlyReport.officeShare') }}</th><th>{{ t('financialUi.actions') }}</th></tr></thead><tbody><tr v-for="r in filtered" :key="r.id"><td><strong>{{r.student_name}}</strong><div class="small muted">{{r.student_code}}</div><span v-if="r.manually_adjusted" class="badge warning" :title="r.manual_adjustment_reason||''">{{ t('financialUi.finance.manualAdjustment') }}</span></td><td>{{r.class_name}}</td><td class="numeric">{{money(r.original_fee)}}</td><td class="numeric">{{money(r.base_fee)}}</td><td>{{t(`registration.${r.proration_rule}`)}}</td><td class="numeric">{{money(r.discount)}}</td><td class="numeric">{{money(r.amount_due)}}</td><td class="numeric">{{money(r.paid_total)}}</td><td class="numeric"><span :class="['badge',Number(r.balance_due)>0?'warning':'success']">{{money(r.balance_due)}}</span></td><td class="numeric">{{money(r.teacher_entitlement)}}</td><td class="numeric">{{money(r.center_entitlement)}}</td><td><div style="display:flex;gap:5px"><button class="btn small-btn" :disabled="Number(r.balance_due)<=0||periodStatus!=='open'" :title="t('financialUi.materials.recordPayment')" @click="startPay(r)"><Wallet :size="15"/>{{t('agreements.recordPayment')}}</button><button class="btn small-btn" :disabled="periodStatus!=='open'||!r.registration_active" :title="t('financialUi.finance.adjustAccount')" v-if="auth.profile.value?.role === 'admin'" @click="startAdjust(r)"><Pencil :size="15"/></button><button class="btn small-btn" :title="t('financialUi.materials.paymentsHistory')" @click="openHistory(r)"><History :size="15"/></button></div></td></tr></tbody></table><div v-if="loading||!filtered.length" class="empty">{{loading?t('financialUi.loading'):t('financialUi.finance.noAccounts')}}</div></div></section></template><div v-else class="card empty">{{ t('financialUi.finance.noMonthAccount') }}</div>
<ModalBox :open="payOpen" :title="t('financialUi.finance.receiveTuition')" @close="payOpen=false"><Notice :message="error" kind="error"/><form v-if="chosen" @submit.prevent="savePayment"><div class="summary-box" style="margin-bottom:18px"><strong>{{chosen.student_name}} — {{chosen.class_name}}</strong><div class="summary-row"><span>{{ t('financialUi.finance.currentBalance') }}</span><strong>{{money(chosen.balance_due)}}</strong></div></div><div class="form-grid"><label>{{ t('financialUi.finance.receivedAmount') }} *<input v-model.number="payAmount" type="number" step="0.01" min="0.01" :max="chosen.balance_due" required/></label><label>{{ t('financialUi.paymentDate') }}<input v-model="paidOn" type="date" required/></label><label>{{ t('financialUi.finance.paymentMethod') }}<select v-model="payMethod" required><option value="">{{ t('financialUi.finance.choosePaymentMethod') }}</option><option value="cash">{{ t('financialUi.finance.cash') }}</option><option value="bank">{{ t('financialUi.finance.bank') }}</option><option value="other">{{ t('financialUi.expenses.other') }}</option></select></label><label>{{ t('financialUi.finance.reference') }}<input v-model="payNote"/></label></div><div class="form-footer"><button type="button" class="btn" @click="payOpen=false">{{ t('financialUi.cancel') }}</button><button class="btn primary" :disabled="saving">{{ t('financialUi.finance.saveReceipt') }}</button></div></form></ModalBox>
<ModalBox :open="adjustOpen" :title="t('agreements.edit')" @close="adjustOpen=false"><AgreementEditor v-if="chosen && adjustOpen" :membership="chosen" @saved="adjustOpen=false;load()"/></ModalBox>
<ModalBox :open="historyOpen" :title="t('financialUi.finance.paymentHistory')" @close="historyOpen=false"><p v-if="chosen" class="hint" style="margin-bottom:15px">{{chosen.student_name}} — {{chosen.class_name}}</p><div v-if="!history.length" class="empty">{{ t('financialUi.materials.noPayments') }}</div><div v-for="p in history" :key="p.id" class="quick-item" style="margin-bottom:9px"><div><strong>{{money(p.amount)}}</strong><div class="small muted">{{p.paid_on}} · {{p.method}} <span v-if="p.voided_at"> · {{ t('financialUi.voided') }}: {{p.void_reason}}</span></div></div><button v-if="!p.voided_at&&periodStatus==='open'" class="btn small-btn danger" @click="voidPay(p)">{{ t('financialUi.voidWithReason') }}</button></div></ModalBox>
<ModalBox :open="receiptOpen" :title="t('financialUi.finance.receiptTitle')" @close="receiptOpen=false"><div v-if="receipt" class="receipt-paper" id="fee-receipt"><OfficialLogo size="report"/><h2>REAL STAR</h2><p>{{ t('financialUi.finance.officialReceipt') }}</p><div class="receipt-meta"><span>{{ t('financialUi.finance.receiptNumber') }}</span><strong>{{receipt.receipt_number||receipt.id}}</strong></div><div class="receipt-meta"><span>{{ t('financialUi.date') }}</span><strong>{{receipt.paid_on}}</strong></div><div class="receipt-meta"><span>{{ t('financialUi.student') }}</span><strong>{{receipt.student_name}}</strong></div><div class="receipt-meta"><span>{{ t('financialUi.finance.studentId') }}</span><strong>{{receipt.student_code}}</strong></div><div class="receipt-meta"><span>{{ t('financialUi.class') }}</span><strong>{{receipt.class_name}}</strong></div><div class="receipt-meta"><span>{{ t('financialUi.finance.receivedAmountLabel') }}</span><strong>{{money(receipt.amount)}}</strong></div><p style="margin-top:25px;font-size:11px">{{ t('financialUi.finance.issuedBy') }}</p></div><div class="receipt-controls no-print"><button class="btn primary" @click="printReceipt"><ReceiptText :size="17"/> {{ t('financialUi.finance.printReceipt') }}</button><button class="btn" @click="receiptOpen=false">{{ t('common.close') }}</button></div></ModalBox>
</div></template>
